// ================= eKombe backend =================
const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const path = require('path');
const store = require('./store');
const B = require('./bracket');

const app = express();
app.use(express.json({limit:'6mb'})); // larger limit for match-proof screenshots
// ---- Embedded pages (self-contained: no separate HTML files needed) ----
const LANDING_HTML = Buffer.from('','base64').toString('utf8');
const INDEX_HTML = Buffer.from('','base64').toString('utf8');
const ADMIN_HTML = Buffer.from('','base64').toString('utf8');
app.get('/', (req,res)=> res.type('html').send(LANDING_HTML));   // landing = front door
app.get('/app', (req,res)=> res.type('html').send(INDEX_HTML));  // the actual app
app.get('/admin', (req,res)=> res.type('html').send(ADMIN_HTML)); // owner dashboard

const JWT_SECRET = process.env.JWT_SECRET || 'ekombe-dev-secret-change-me';
const PAYMENTS_LIVE = false; // flip on once Selcom pass-through is wired
// FREE-ONLY LAUNCH: no money changes hands. All tournaments are free, no fees recorded.
// The pass-through payment code below stays in place, dormant. Set to false (and register
// your business + wire Selcom) to enable paid tournaments later.
const FREE_ONLY = true;

// ---- currency + pass-through fee config (USD base -> local) ----
const CUR = {
  TZ:{code:'TSh',rate:2500}, KE:{code:'KSh',rate:130}, UG:{code:'USh',rate:3800},
  NG:{code:'₦',rate:1500}, GH:{code:'₵',rate:15}, ZA:{code:'R',rate:18},
  US:{code:'$',rate:1}, GB:{code:'£',rate:0.79}, EU:{code:'€',rate:0.92},
  IN:{code:'₹',rate:83}, BR:{code:'R$',rate:5.1}, OT:{code:'$',rate:1}
};
const roundFee = v => v>=100?Math.round(v/10)*10 : v>=1?Math.round(v) : Math.round(v*100)/100;
const creationFee = c => roundFee(0.10 * (CUR[c]||CUR.OT).rate);
const PRIZE_CUT = 0.10;
const curCode = c => (CUR[c]||CUR.OT).code;

// ---- helpers ----
function sign(u){ return jwt.sign({ id:u.id, email:u.email }, JWT_SECRET, { expiresIn:'30d' }); }
function auth(req,res,next){
  const h=req.headers.authorization||'';
  const tok=h.startsWith('Bearer ')?h.slice(7):null;
  if(!tok) return res.status(401).json({error:'not signed in'});
  try{ req.uid=jwt.verify(tok, JWT_SECRET).id; next(); }
  catch(e){ res.status(401).json({error:'session expired'}); }
}
const publicUser = u => ({ id:u.id, name:u.name, email:u.email, country:u.country, phone:u.phone, wins:u.wins, losses:u.losses, played:u.played, avatar:u.avatar||null });
function tx(user_id, tournament_id, type, amount, currency){
  store.addTx({ user_id, tournament_id, type, amount, currency, status: PAYMENTS_LIVE?'success':'pending' });
}
function shape(t){
  const out = Object.assign({}, t);
  out.paid = !!t.paid;
  out.bracket = t.bracket ? (typeof t.bracket==='string'?JSON.parse(t.bracket):t.bracket) : null;
  out.players = store.players(t.id);
  out.pending = store.pendingRegs(t.id).map(r=>({ user_id:r.user_id, name:r.display_name }));
  out.currency = curCode(t.country);
  if(out.bracket && t.format==='league') out.standings = B.standings(out.bracket.players, out.bracket.rounds);
  return out;
}

// ================= AUTH =================
app.post('/api/register', (req,res)=>{
  const { name,email,password,country,phone } = req.body||{};
  if(!name||!email||!password) return res.status(400).json({error:'name, email and password are required'});
  if(String(password).length<6) return res.status(400).json({error:'password must be at least 6 characters'});
  if(store.userByEmail(email)) return res.status(409).json({error:'an account with this email already exists'});
  const hash=bcrypt.hashSync(String(password),10);
  const u=store.createUser({ name, email, password:hash, country, phone });
  res.json({ token:sign(u), user:publicUser(u) });
});

app.post('/api/login', (req,res)=>{
  const { email,password } = req.body||{};
  const u=store.userByEmail(email);
  if(!u || !bcrypt.compareSync(String(password||''), u.password)) return res.status(401).json({error:'wrong email or password'});
  res.json({ token:sign(u), user:publicUser(u) });
});

app.get('/api/me', auth, (req,res)=>{
  const u=store.userById(req.uid);
  if(!u) return res.status(404).json({error:'user not found'});
  res.json({ user:publicUser(u) });
});

// Upload / change profile picture
app.post('/api/me/avatar', auth, async (req,res)=>{
  try{
    const image=req.body&&req.body.image;
    if(!image||typeof image!=='string') return res.status(400).json({error:'no image provided'});
    const m=/^data:(image\/(?:png|jpe?g|webp));base64,(.+)$/i.exec(image);
    if(!m) return res.status(400).json({error:'invalid image'});
    if(m[2].length>8*1024*1024) return res.status(413).json({error:'image too large'});
    const id=await store.saveEvidence({ kind:'avatar', ref_id:req.uid, uploader:null, mime:m[1], image:m[2] });
    store.setAvatar(req.uid, id);
    res.json({ avatar:id });
  }catch(e){ console.error('avatar upload failed:', e.message); res.status(500).json({error:'upload failed'}); }
});

// ---- Password reset with emailed verification code ----
let transporter=null;
function initMail(){
  if(process.env.SMTP_DRYRUN){ // testing aid: pretend-send without a real server
    try{ transporter=require('nodemailer').createTransport({jsonTransport:true}); console.log('eKombe email: DRYRUN'); }catch(e){}
    return;
  }
  if(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS){
    try{
      const nodemailer=require('nodemailer');
      transporter=nodemailer.createTransport({
        host:process.env.SMTP_HOST, port:Number(process.env.SMTP_PORT||587),
        secure:Number(process.env.SMTP_PORT)===465,
        auth:{ user:process.env.SMTP_USER, pass:process.env.SMTP_PASS }
      });
      console.log('eKombe email: SMTP configured — password reset by email is ON.');
    }catch(e){ console.error('email setup failed:', e.message); transporter=null; }
  } else {
    console.log('eKombe email: not configured — set SMTP_* env vars to enable password reset.');
  }
}
initMail();
const MAIL_FROM = process.env.SMTP_FROM || process.env.SMTP_USER;
async function sendResetEmail(to, code){
  await transporter.sendMail({
    from:`eKombe <${MAIL_FROM}>`, to,
    subject:'Your eKombe password reset code',
    text:`Your eKombe password reset code is: ${code}\n\nIt expires in 15 minutes. If you didn't request this, ignore this email.`,
    html:`<div style="font-family:Segoe UI,Arial,sans-serif"><p>Your eKombe password reset code is:</p>
      <p style="font-size:28px;font-weight:800;letter-spacing:5px">${code}</p>
      <p>It expires in 15 minutes. If you didn't request this, you can safely ignore this email.</p></div>`
  });
}

app.post('/api/reset/request', async (req,res)=>{
  const email=String((req.body&&req.body.email)||'').trim().toLowerCase();
  if(!email) return res.status(400).json({error:'email is required'});
  if(!transporter) return res.status(503).json({error:'Password reset by email is not set up yet.'});
  const u=store.userByEmail(email);
  const code=''+Math.floor(100000+Math.random()*900000); // 6-digit
  if(u){
    store.setResetCode(email, bcrypt.hashSync(code,8), Date.now()+15*60*1000);
    try{ await sendResetEmail(u.email, code); }
    catch(e){ console.error('reset email send failed:', e.message); return res.status(500).json({error:'could not send the email — please try again'}); }
  }
  // Respond the same whether or not the account exists (privacy).
  const out={ ok:true };
  if(process.env.RESET_DEBUG && u) out.devCode=code; // testing hook only; never set in production
  res.json(out);
});

app.post('/api/reset/confirm', (req,res)=>{
  const email=String((req.body&&req.body.email)||'').trim().toLowerCase();
  const code=String((req.body&&req.body.code)||'').trim();
  const password=(req.body&&req.body.password)||'';
  if(!email||!code||!password) return res.status(400).json({error:'email, code and new password are required'});
  if(String(password).length<6) return res.status(400).json({error:'new password must be at least 6 characters'});
  const rc=store.getResetCode(email);
  if(!rc) return res.status(400).json({error:'no reset request found — request a new code'});
  if(Date.now()>rc.expires){ store.clearResetCode(email); return res.status(400).json({error:'code expired — request a new one'}); }
  if(rc.tries>=5){ store.clearResetCode(email); return res.status(429).json({error:'too many wrong attempts — request a new code'}); }
  if(!bcrypt.compareSync(code, rc.hash)){ store.bumpResetTries(email); return res.status(401).json({error:'wrong code'}); }
  const u=store.userByEmail(email);
  if(!u){ store.clearResetCode(email); return res.status(404).json({error:'account not found'}); }
  store.setPassword(u.id, bcrypt.hashSync(String(password),10));
  store.clearResetCode(email);
  res.json({ token:sign(u), user:publicUser(u) });
});

// ================= TOURNAMENTS =================
app.get('/api/tournaments', (req,res)=> res.json(store.listTournaments().map(shape)));

app.get('/api/tournaments/:id', (req,res)=>{
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  res.json(shape(t));
});

app.post('/api/tournaments', auth, (req,res)=>{
  let { name,format,size,paid,entry,logoId } = req.body||{};
  if(!name||!format) return res.status(400).json({error:'name and format required'});
  if(FREE_ONLY){ paid=0; entry=0; }               // free-only launch
  const u=store.userById(req.uid);
  const t=store.createTournament({ name, format, size:size||8, paid:paid?1:0, entry:entry||0, country:u.country, owner_id:u.id, logo:logoId?Number(logoId):null });
  store.addRegistration(t.id, u.id, u.name, paid?'held':'none', 'approved'); // creator auto-joins (approved)
  if(!FREE_ONLY) tx(u.id, t.id, 'creation_fee', creationFee(u.country), curCode(u.country)); // pass-through
  res.json(shape(t));
});

// Owner sets/changes the tournament logo
app.post('/api/tournaments/:id/logo', auth, async (req,res)=>{
  try{
    const t=store.tournament(req.params.id);
    if(!t) return res.status(404).json({error:'not found'});
    if(t.owner_id!==req.uid) return res.status(403).json({error:'only the organizer can change the logo'});
    const image=req.body&&req.body.image;
    const m=/^data:(image\/(?:png|jpe?g|webp));base64,(.+)$/i.exec(image||'');
    if(!m) return res.status(400).json({error:'invalid image'});
    if(m[2].length>8*1024*1024) return res.status(413).json({error:'image too large'});
    const id=await store.saveEvidence({ kind:'logo', ref_id:t.id, uploader:null, mime:m[1], image:m[2] });
    store.updateTournament(t.id, { logo:id });
    res.json(shape(store.tournament(t.id)));
  }catch(e){ res.status(500).json({error:'upload failed'}); }
});

app.post('/api/tournaments/:id/join', auth, (req,res)=>{
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  if(t.status!=='open') return res.status(400).json({error:'tournament already started'});
  if(store.players(t.id).length>=t.size) return res.status(400).json({error:'tournament is full'});
  const u=store.userById(req.uid);
  if(store.regByUser(t.id,u.id)) return res.status(409).json({error:'already requested to join'});
  store.addRegistration(t.id, u.id, u.name, t.paid?'held':'none', 'pending'); // needs organizer approval
  res.json(shape(t));
});

// Organizer approves a pending join request
app.post('/api/tournaments/:id/approve', auth, (req,res)=>{
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  if(t.owner_id!==req.uid) return res.status(403).json({error:'only the organizer can approve'});
  if(store.players(t.id).length>=t.size) return res.status(400).json({error:'tournament is already full'});
  const uid=Number(req.body&&req.body.userId);
  const r=store.regByUser(t.id, uid);
  if(!r || r.status!=='pending') return res.status(404).json({error:'no pending request from that player'});
  store.approveReg(t.id, uid);
  if(t.paid) tx(uid, t.id, 'entry_hold', t.entry, curCode(t.country)); // HELD until end
  res.json(shape(store.tournament(t.id)));
});

// Organizer rejects/removes a join request
app.post('/api/tournaments/:id/reject', auth, (req,res)=>{
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  if(t.owner_id!==req.uid) return res.status(403).json({error:'only the organizer can reject'});
  const uid=Number(req.body&&req.body.userId);
  store.removeReg(t.id, uid);
  res.json(shape(store.tournament(t.id)));
});

// dev/demo helper: fill with bot players so you can test brackets solo
app.post('/api/tournaments/:id/start', auth, (req,res)=>{
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  if(t.owner_id!==req.uid) return res.status(403).json({error:'only the organizer can start'});
  if(t.status!=='open') return res.status(400).json({error:'already started'});
  const ps=store.players(t.id);
  if(ps.length<2) return res.status(400).json({error:'need at least 2 players'});
  if(t.format==='double' && ![4,8,16].includes(ps.length)) return res.status(400).json({error:'double elim needs exactly 4, 8 or 16 players'});
  if(t.format==='groups' && ps.length<8) return res.status(400).json({error:'groups need 8+ players'});
  const bracket=B.generate(t.format, ps);
  store.updateTournament(t.id, { bracket, status:'live' });
  res.json(shape(store.tournament(t.id)));
});

app.post('/api/tournaments/:id/report', auth, (req,res)=>{
  const { matchId, s1, s2, pkWinner, evidenceId } = req.body||{};
  const t=store.tournament(req.params.id);
  if(!t) return res.status(404).json({error:'not found'});
  if(t.status!=='live') return res.status(400).json({error:'tournament is not live'});
  const bracket=t.bracket;
  const m=B.findMatch(bracket, matchId);
  if(!m) return res.status(404).json({error:'match not found'});
  const p1=m.p1, p2=m.p2;
  let result;
  const sc1=Math.max(0,Math.floor(Number(s1)||0)), sc2=Math.max(0,Math.floor(Number(s2)||0));
  try{ result=B.report(bracket, matchId, sc1, sc2, pkWinner); }
  catch(e){ return res.status(400).json({error:e.message}); }
  if(evidenceId) m.evidence = evidenceId; // attach proof screenshot to this match
  const winner=m.winner, loser=(winner===p1)?p2:p1;
  bumpStat(t.id, winner, true); bumpStat(t.id, loser, false);

  let payout=null;
  if(result.champion){
    store.updateTournament(t.id, { status:'done', champion:result.champion });
    if(t.paid) payout=doPayout(t, bracket);
  }
  store.updateTournament(t.id, { bracket });
  res.json({ tournament: shape(store.tournament(t.id)), champion: result.champion, payout });
});

function bumpStat(tid, name, win){
  const reg=store.regByName(tid, name);
  if(reg && reg.user_id) store.addResult(reg.user_id, win);
}

// PASS-THROUGH payout: distribute held entry fees to podium, keep 10% cut. No stored balances.
function podium(t, b){
  if(b.type==='league'){ const st=B.standings(b.players,b.rounds); return [st[0]&&st[0].p, st[1]&&st[1].p, st[2]&&st[2].p]; }
  let final;
  if(b.type==='single') final=b.rounds[b.rounds.length-1][0];
  else if(b.type==='double') final=b.gf[0];
  else if(b.type==='groups') final=b.knockout && b.knockout.rounds[b.knockout.rounds.length-1][0];
  if(!final) return [t.champion,null,null];
  const runner = final.winner===final.p1?final.p2:final.p1;
  return [final.winner, runner, null];
}
function doPayout(t, b){
  const pool = t.entry * store.players(t.id).length;
  const cut = Math.round(pool*PRIZE_CUT);
  const dist = pool - cut;
  const [first,second,third] = podium(t,b);
  const shares = third ? [0.6,0.3,0.1] : second ? [0.667,0.333,0] : [1,0,0];
  const names=[first,second,third], distributed=[]; const cur=curCode(t.country);
  tx(t.owner_id, t.id, 'prizepool_cut', cut, cur);
  names.forEach((nm,i)=>{
    if(!nm||shares[i]<=0) return;
    const amt=Math.round(dist*shares[i]);
    const reg=store.regByName(t.id,nm);
    tx(reg?reg.user_id:null, t.id, 'prize_payout', amt, cur);
    distributed.push({ place:i+1, name:nm, amount:amt });
  });
  return { pool, cut, currency:cur, distributed, live:PAYMENTS_LIVE };
}

// ================= EVIDENCE (match-proof screenshots) =================
app.post('/api/evidence', auth, async (req,res)=>{
  try{
    const { kind, refId, image } = req.body||{};
    if(!image || typeof image!=='string') return res.status(400).json({error:'no image provided'});
    const m=/^data:(image\/(?:png|jpe?g|webp));base64,(.+)$/i.exec(image);
    if(!m) return res.status(400).json({error:'invalid image format'});
    const mime=m[1], b64=m[2];
    if(b64.length > 8*1024*1024) return res.status(413).json({error:'image too large — please use a smaller screenshot'});
    const u=store.userById(req.uid);
    const id=await store.saveEvidence({ kind:kind||'match', ref_id:refId?Number(refId):null, uploader:u?u.name:null, mime, image:b64 });
    res.json({ id });
  }catch(e){ console.error('evidence upload failed:', e.message); res.status(500).json({error:'upload failed'}); }
});
app.get('/api/evidence/:id', async (req,res)=>{
  try{
    const ev=await store.getEvidence(req.params.id);
    if(!ev) return res.status(404).send('Not found');
    res.set('Content-Type', ev.mime);
    res.set('Cache-Control','public, max-age=31536000, immutable');
    res.send(Buffer.from(ev.image,'base64'));
  }catch(e){ res.status(500).send('error'); }
});

// ================= BATTLES (free 1v1) =================
function shapeB(b){ return { id:b.id, host:b.host_name, host_id:b.host_id, opp:b.opp_name, opp_id:b.opp_id,
  status:b.status, winner:b.winner_name, s1:b.s1, s2:b.s2, country:b.country, evidence:b.evidence||null }; }

app.get('/api/battles', (req,res)=> res.json(store.listBattles().map(shapeB)));

app.post('/api/battles', auth, (req,res)=>{
  const u=store.userById(req.uid);
  const b=store.createBattle({ host_id:u.id, host_name:u.name, country:u.country });
  res.json(shapeB(b));
});

app.post('/api/battles/:id/accept', auth, (req,res)=>{
  const b=store.battle(req.params.id); if(!b) return res.status(404).json({error:'battle not found'});
  if(b.status!=='open') return res.status(400).json({error:'this battle is no longer open'});
  if(b.host_id===req.uid) return res.status(400).json({error:'you cannot accept your own battle'});
  const u=store.userById(req.uid);
  store.updateBattle(b.id,{ opp_id:u.id, opp_name:u.name, status:'live' });
  res.json(shapeB(store.battle(b.id)));
});

app.post('/api/battles/:id/report', auth, (req,res)=>{
  const b=store.battle(req.params.id); if(!b) return res.status(404).json({error:'battle not found'});
  if(b.status!=='live') return res.status(400).json({error:'this battle is not live'});
  if(req.uid!==b.host_id && req.uid!==b.opp_id) return res.status(403).json({error:'only players in this battle can report the result'});
  const s1=Math.max(0,parseInt(req.body&&req.body.s1,10)||0);
  const s2=Math.max(0,parseInt(req.body&&req.body.s2,10)||0);
  let winnerId, winnerName; // s1=host, s2=opponent; draw -> pkWinner (default host)
  if(s1>s2){ winnerId=b.host_id; winnerName=b.host_name; }
  else if(s2>s1){ winnerId=b.opp_id; winnerName=b.opp_name; }
  else if(req.body && req.body.pkWinner==='opp'){ winnerId=b.opp_id; winnerName=b.opp_name; }
  else { winnerId=b.host_id; winnerName=b.host_name; }
  const patch={ status:'done', s1, s2, winner_id:winnerId, winner_name:winnerName };
  if(req.body && req.body.evidenceId) patch.evidence=req.body.evidenceId; // proof screenshot
  store.updateBattle(b.id, patch);
  store.addResult(winnerId, true);
  store.addResult(winnerId===b.host_id? b.opp_id : b.host_id, false);
  res.json(shapeB(store.battle(b.id)));
});

// ================= ADMIN (owner-only) =================
// Protected by the ADMIN_KEY environment variable. If ADMIN_KEY is not set,
// the admin area is disabled entirely (safe default).
function admin(req,res,next){
  const key=process.env.ADMIN_KEY;
  if(!key) return res.status(403).json({error:'Admin is not enabled. Set an ADMIN_KEY on the server.'});
  if(String(req.headers['x-admin-key']||'')!==key) return res.status(401).json({error:'Wrong admin key.'});
  next();
}
app.get('/api/admin/overview', admin, (req,res)=>{
  const users=store.allUsers();
  const tournaments=store.listTournaments();
  const battles=store.listBattles();
  const cnt=(arr,f)=>arr.filter(f).length;
  res.json({
    stats:{
      players:users.length,
      tournaments:tournaments.length,
      tOpen:cnt(tournaments,t=>t.status==='open'), tLive:cnt(tournaments,t=>t.status==='live'), tDone:cnt(tournaments,t=>t.status==='done'),
      battles:battles.length,
      bOpen:cnt(battles,b=>b.status==='open'), bLive:cnt(battles,b=>b.status==='live'), bDone:cnt(battles,b=>b.status==='done')
    },
    users:users.slice().sort((a,b)=>b.id-a.id).map(u=>({ id:u.id, name:u.name, email:u.email, country:u.country,
      wins:u.wins, losses:u.losses, played:u.played, created_at:u.created_at })),
    tournaments:tournaments.map(t=>({ id:t.id, name:t.name, format:t.format, status:t.status,
      players:store.players(t.id).length, size:t.size, champion:t.champion, created_at:t.created_at })),
    battles:battles.map(b=>({ id:b.id, host:b.host_name, opp:b.opp_name, status:b.status, winner:b.winner_name, created_at:b.created_at }))
  });
});

// ================= EXTRAS =================
app.get('/api/leaderboard', (req,res)=>{
  res.json(store.topPlayers(100).map((r,i)=>({ rank:i+1, name:r.name, country:r.country, avatar:r.avatar||null,
    wins:r.wins, losses:r.losses, played:r.played, pts:r.wins*3, winrate:r.played?Math.round(r.wins/r.played*100):0 })));
});
app.get('/api/transactions/me', auth, (req,res)=> res.json(store.txByUser(req.uid)));
app.get('/api/config', (req,res)=> res.json({ freeOnly:FREE_ONLY, paymentsLive:PAYMENTS_LIVE, emailReset:!!transporter, prizeCutPct:PRIZE_CUT*100, currencies:CUR,
  note:'Free-only launch: no money changes hands. Pass-through payments are built but dormant (set FREE_ONLY=false + wire Selcom to enable).' }));

const PORT=process.env.PORT||3000;
store.init()
  .then(()=> app.listen(PORT, ()=>console.log('eKombe backend running on http://localhost:'+PORT)))
  .catch(e=>{ console.error('Failed to start — could not load data store:', e.message); process.exit(1); });
